#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <set>
using namespace std;

int main(){
vector<double> observed={1,2,3,4,5};
vector<double> baseline={2,2,2,2,2};
vector<double> candidate={1.2,2.1,3.1,3.7,5.3};
double meanGain=0;
for(int t=0;t<int(observed.size());t++){
    double lossBase=pow(baseline[t]-observed[t],2);
    double lossModel=pow(candidate[t]-observed[t],2);
    meanGain+=(lossBase-lossModel)/observed.size();
    cout<<t<<" loss gain "<<lossBase-lossModel<<endl;
}
cout<<"Average gain "<<meanGain<<endl;
    return 0;
}

