#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <set>
using namespace std;

int main(){
vector<double> x={1,2,3,4,5},y={2,4,5,4,6};
double mx=0,my=0,xx=0,xy=0;
for(int i=0;i<int(x.size());i++){mx+=x[i]/x.size();my+=y[i]/x.size();}
for(int i=0;i<int(x.size());i++){
    xx+=pow(x[i]-mx,2);
    xy+=(x[i]-mx)*(y[i]-my);
}
double beta=xy/xx,alpha=my-beta*mx,sumResidual=0,sumResidualX=0;
for(int i=0;i<int(x.size());i++){
    double error=y[i]-alpha-beta*x[i];
    sumResidual+=error;sumResidualX+=error*x[i];
}
cout<<"Intercept "<<alpha<<" slope "<<beta<<endl;
cout<<"Normal equations "<<sumResidual<<" "<<sumResidualX<<endl;
    return 0;
}

