int main(){
double observed=1.2,mu[2]={0,2},sigma[2]={1,0.6},weight[2]={0.3,0.7};
double logNumerator[2],peak=-1e100;
for(int k=0;k<2;k++){
    double z=(observed-mu[k])/sigma[k];
    logNumerator[k]=log(weight[k])-log(sigma[k])-0.5*z*z;
    peak=max(peak,logNumerator[k]);
}
double sum=exp(logNumerator[0]-peak)+exp(logNumerator[1]-peak);
for(int k=0;k<2;k++)cout<<k<<" "<<exp(logNumerator[k]-peak)/sum<<endl;
    return 0;
}

