#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <set>
using namespace std;

int main(){
vector<vector<double>> early={{0.01,0.02},{-0.01,-0.01},
    {0.02,0.03},{-0.02,-0.02}};
vector<vector<double>> late={{0.01,-0.01},{0.02,0.01},
    {-0.01,0.02},{-0.02,0.03}};
auto correlation=[](const vector<vector<double>>& data){
    double mx=0,my=0,xx=0,yy=0,xy=0;
    for(const auto& row:data){mx+=row[0]/data.size();my+=row[1]/data.size();}
    for(const auto& row:data){
        double a=row[0]-mx,b=row[1]-my;
        xx+=a*a;yy+=b*b;xy+=a*b;
    }
    return xy/sqrt(xx*yy);
};
cout<<"Early correlation "<<correlation(early)
    <<" late correlation "<<correlation(late)<<endl;
    return 0;
}

