#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <set>
using namespace std;

int main(){
vector<vector<double>> scenario={{-0.1,-0.03},{0.02,-0.08},{0.01,0.02}};
double worstRisk=1e100,bestWeight=0;
for(int i=0;i<=10;i++){
    double wa=i/10.0,wb=1-wa;
    vector<double> loss;
    for(const auto& outcome:scenario)
        loss.push_back(-(wa*outcome[0]+wb*outcome[1]));
    sort(loss.begin(),loss.end());
    double tail=loss.back();
    if(tail<worstRisk){worstRisk=tail;bestWeight=wa;}
}
cout<<"Worst-case risk minimizing weight A "<<bestWeight
    <<" worst loss "<<worstRisk<<endl;
    return 0;
}
